use gpui::*;
use resume::*;
use std::borrow::Cow;

mod resume;

struct Assets;
impl AssetSource for Assets {
    fn load(&self, _path: &str) -> Result<Option<Cow<'static, [u8]>>> {
        std::fs::read(_path)
            .map(Into::into)
            .map_err(Into::into)
            .map(Some)
    }

    fn list(&self, _path: &str) -> Result<Vec<SharedString>> {
        Ok(std::fs::read_dir(_path)?
            .filter_map(|entry| {
                Some(SharedString::from(
                    entry.ok()?.path().to_string_lossy().to_string(),
                ))
            })
            .collect::<Vec<_>>())
    }
}

fn main() {
    App::new().with_assets(Assets).run(|cx: &mut AppContext| {
        cx.activate(true);
        cx.on_action(quit);
        cx.set_menus(vec![Menu {
            name: "resume_viewer".into(),
            items: vec![MenuItem::action("Quit", Quit)],
        }]);
        cx.bind_keys(vec![KeyBinding::new("cmd-q", Quit, None)]);

        let primary_display_bounds = cx.primary_display().unwrap().bounds();

        let window_options = WindowOptions {
            window_bounds: Some(WindowBounds::Windowed(
                primary_display_bounds.inset(px(100.)),
            )),
            ..WindowOptions::default()
        };
        cx.open_window(window_options, |cx| cx.new_view(|_cx| init_resume()))
            .unwrap();
    })
}

